import json, os, re
here = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "web", "js", "i18n")
seen = set()
for en, fr, es in ROWS:
    if en in seen:
        raise SystemExit(f"duplicate key: {en}")
    seen.add(en)
    for tr in (fr, es):
        a = sorted(re.findall(r"\{(\w+)\}", en)); b = sorted(re.findall(r"\{(\w+)\}", tr))
        if a != b: raise SystemExit(f"placeholder mismatch: {en} -> {tr}")
for lang, idx, name in (("fr", 1, "Français (Canada)"), ("es", 2, "Español")):
    d = {}
    for row in ROWS:
        d[row[0]] = row[idx]
    body = ",\n".join(f"  {json.dumps(k, ensure_ascii=False)}: {json.dumps(v, ensure_ascii=False)}" for k, v in d.items())
    with open(os.path.join(here, f"{lang}.js"), "w") as f:
        f.write(f"// {name}. Built from source.py, edit there.\nexport default {{\n{body},\n}};\n")
print(len(ROWS), "rows")
